mapper.select:
/*selectMasterCmClPurchaseTaxsheetIndividualCreationList*/
/* ICOMGRDT.PROCESS_TYPE = '0' 직납 또는 ICOMGRDT.PROCESS_TYPE = '2' 재고 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' /* OPA파트로 설정 */ ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , DECODE(BYIT.TAX_TYPE, '12',GR.AGENT_ITEM_AMT, ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER)))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , GR.AGENT AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , 'Y' AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , BYIT.TAX_TYPE , USR.USER_NAME_LOC , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = GR.AGENT) AS SP_TYPE FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , V_VOC_ICOMCMPY BCM /* (ICOMCMPY - 회원사정보, MIS_BUYER_MNG - 고객사별 담당자 정보) */ , ICOMLUSR USR /* 발주자 정보 */ , ICOMBYIT BYIT WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND BCM.SYS_TYPE = 'KA' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND GR.AGENT = CM.COM_CODE AND GR.BUYER = BCM.COM_CODE AND GR.AP_BILL_FLAG = 'N' AND GR.AR_BILL_FLAG = 'Y' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO AND GR.PROCESS_TYPE IN ('0','2') AND POHD.DOC_TYPE <> 'X' AND GR.BUYER = COD.TEXT1(+) AND GR.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND GR.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA') AND POHD.ADD_USER_ID = USR.USER_ID(+)
AND GR.BUYER = #{st_buyer_code}
AND GR.AGENT = #{st_agent_code}
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) = #{st_tax_type} /* 과세구분 */
AND GR.BUYER IN ( SELECT GR.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND USR.USER_NAME_LOC LIKE '%' || #{st_purchaser_name} || '%'
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , PODT.WAREHOUSE_CODE AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , 'Y' AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) AS TAX_TYPE , USR.USER_NAME_LOC , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = PODT.WAREHOUSE_CODE) AS SP_TYPE FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , V_VOC_ICOMCMPY BCM /* (ICOMCMPY - 회원사정보, MIS_BUYER_MNG - 고객사별 담당자 정보) */ , ICOMLUSR USR /* 발주자 정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND BCM.SYS_TYPE = 'KA' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = CM.COM_CODE /* GR.AGENT = '물류센타코드' , PODT.WAREHOUSE_CODE = '실공급사코드' */ AND GR.BUYER = BCM.COM_CODE AND GR.AP_BILL_FLAG = 'N' AND GR.AR_BILL_FLAG = 'Y' AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.BUYER = COD.TEXT1(+) AND PODT.WAREHOUSE_CODE = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND PODT.WAREHOUSE_CODE NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA') AND POHD.ADD_USER_ID = USR.USER_ID(+)
AND GR.BUYER = #{st_buyer_code}
AND PODT.WAREHOUSE_CODE = #{st_agent_code} /* PODT.WAREHOUSE_CODE = '실공급사코드' */
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) = #{st_tax_type} /* 과세구분 */
AND GR.BUYER IN ( SELECT GR.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND USR.USER_NAME_LOC LIKE '%' || #{st_purchaser_name} || '%'
UNION ALL
/* ICOMGRDT.PROCESS_TYPE = '1' 재고 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , GR.GR_DATE AS GR_DATE , ROUND((GR.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(GR.BUYER))) AS GR_AMT , GR.PO_NO AS PO_NO , GR.GR_NO AS GR_NO , GR.GR_SEQ AS GR_SEQ , GR.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = GR.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN GR.AP_CLOSE_DEPT IS NOT NULL THEN GR.AP_CLOSE_DEPT WHEN GR.AR_CLOSE_DEPT IS NOT NULL THEN GR.AR_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = GR.BUYER AND YEAR = SUBSTR(GR.GR_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , GR.AGENT AS AGENT , GR.DESCRIPTION AS DESCRIPTION , GR.SPECIFICATION AS SPECIFICATION , SUBSTR(GR.GR_DATE,1,6) , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , 'Y' AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) AS TAX_TYPE , USR.USER_NAME_LOC , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = GR.AGENT) AS SP_TYPE FROM ICOMGRDT GR /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , V_VOC_ICOMCMPY BCM /* (ICOMCMPY - 회원사정보, MIS_BUYER_MNG - 고객사별 담당자 정보) */ , ICOMLUSR USR /* 발주자 정보 */ WHERE 1=1 AND GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.STATUS <> 'D' AND POHD.STATUS <> 'D' AND BCM.SYS_TYPE = 'KA' AND PODT.STATUS <> 'D' AND GR.AGENT = CM.COM_CODE AND GR.BUYER = BCM.COM_CODE AND GR.AP_BILL_FLAG = 'N' AND GR.BUYER IN (select text1 from ICOMCOD1 WHERE TYPE = 'HUB') AND GR.BUYER = POHD.BUYER AND GR.PO_NO = POHD.PO_NO AND GR.BUYER = PODT.BUYER AND GR.PO_NO = PODT.PO_NO AND GR.PO_SEQ = PODT.PO_SEQ AND GR.PROCESS_TYPE = '1' AND GR.AGENT NOT IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'S' AND FLAG = 'Y') AND POHD.DOC_TYPE <> 'X' AND GR.BUYER = COD.TEXT1(+) AND GR.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND GR.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA') AND POHD.ADD_USER_ID = USR.USER_ID(+)
AND GR.BUYER = #{st_buyer_code}
AND GR.AGENT = #{st_agent_code}
AND (GR.PO_NO LIKE #{st_po_no} || '%' OR GR.GR_NO LIKE #{st_po_no} || '%')
AND (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) = #{st_tax_type} /* 과세구분 */
AND GR.BUYER IN ( SELECT GR.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND USR.USER_NAME_LOC LIKE '%' || #{st_purchaser_name} || '%'
ORDER BY GR_DATE , PO_NO , GR_NO , GR_SEQ

/*selectMasterCmClPurchaseTaxsheetIndividualCreationList_v2*/
/* ICOMIVDT.PROCESS_TYPE = '0' 직납 또는 ICOMIVDT.PROCESS_TYPE = '2' 재고 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' /* OPA파트로 설정 */ ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , DECODE(BYIT.TAX_TYPE, '12',IV.AGENT_ITEM_AMT, ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER)))) AS INV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV_SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , IV.AGENT AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , 'Y' AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , BYIT.TAX_TYPE , USR.USER_NAME_LOC , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = IV.AGENT) AS SP_TYPE FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , V_VOC_ICOMCMPY BCM /* (ICOMCMPY - 회원사정보, MIS_BUYER_MNG - 고객사별 담당자 정보) */ , ICOMLUSR USR /* 발주자 정보 */ , ICOMBYIT BYIT WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND BCM.SYS_TYPE = 'KA' AND POHD.STATUS <> 'D' AND PODT.STATUS <> 'D' AND IV.AGENT = CM.COM_CODE AND IV.BUYER = BCM.COM_CODE AND NVL(IV.AP_BILL_FLAG,'N') = 'N' AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO AND IV.PROCESS_TYPE IN ('0','2') AND POHD.DOC_TYPE <> 'X' AND IV.BUYER = COD.TEXT1(+) AND IV.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND IV.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA') AND POHD.ADD_USER_ID = USR.USER_ID(+)
AND IV.BUYER = #{st_buyer_code}
AND IV.AGENT = #{st_agent_code}
AND IV.PO_NO LIKE #{st_po_no}
AND (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) = #{st_tax_type} /* 과세구분 */
AND IV.BUYER IN ( SELECT IV.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND USR.USER_NAME_LOC LIKE '%' || #{st_purchaser_name} || '%'
UNION ALL
/* ICOMIVDT.PROCESS_TYPE = '3' VMI 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS INV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV_SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , PODT.WAREHOUSE_CODE AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) AS CL_MON , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , 'Y' AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) AS TAX_TYPE , USR.USER_NAME_LOC , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = PODT.WAREHOUSE_CODE) AS SP_TYPE FROM ICOMIVDT IV /* 구매사별 납품정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , V_VOC_ICOMCMPY BCM /* (ICOMCMPY - 회원사정보, MIS_BUYER_MNG - 고객사별 담당자 정보) */ , ICOMLUSR USR /* 발주자 정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND BCM.SYS_TYPE = 'KA' AND PODT.STATUS <> 'D' AND PODT.WAREHOUSE_CODE = CM.COM_CODE /* IV.AGENT = '물류센타코드' , PODT.WAREHOUSE_CODE = '실공급사코드' */ AND IV.BUYER = BCM.COM_CODE AND NVL(IV.AP_BILL_FLAG,'N') = 'N' AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '3' AND POHD.DOC_TYPE <> 'X' AND PODT.BUYER = COD.TEXT1(+) AND PODT.WAREHOUSE_CODE = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND PODT.WAREHOUSE_CODE NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA') AND POHD.ADD_USER_ID = USR.USER_ID(+)
AND IV.BUYER = #{st_buyer_code}
AND PODT.WAREHOUSE_CODE = #{st_agent_code} /* PODT.WAREHOUSE_CODE = '실공급사코드' */
AND IV.PO_NO LIKE #{st_po_no}
AND (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) = #{st_tax_type} /* 과세구분 */
AND IV.BUYER IN ( SELECT IV.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND USR.USER_NAME_LOC LIKE '%' || #{st_purchaser_name} || '%'
UNION ALL
/* ICOMIVDT.PROCESS_TYPE = '1' 재고 일 경우 */ SELECT (SELECT TEXT4 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NAME , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS SITE_GUBUN_NAME , CM.IRS_NO AS AGENT_IRS_NO , CM.COM_NAME_LOC AS AGENT_NAME , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT , IV.DELIVERY_DATE AS DELIVERY_DATE , ROUND((IV.AGENT_ITEM_AMT/F_GET_VATRATE_NEW(IV.BUYER))) AS INV_AMT , IV.PO_NO AS PO_NO , IV.INV_NO AS INV_NO , IV.INV_SEQ AS INV_SEQ , IV.BUYER AS BUYER , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE = IV.BUYER) AS BUYER_NM , (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_IRS_NO , CASE WHEN IV.AP_CLOSE_DEPT IS NOT NULL THEN IV.AP_CLOSE_DEPT WHEN COD.CODE IS NOT NULL THEN '017' ELSE (SELECT MAX(KEP_DEPT) FROM MIS_BUYER_MNG WHERE BUYER = IV.BUYER AND YEAR = SUBSTR(IV.DELIVERY_DATE,1,4) AND ITEM_GROUP = 'M' AND STATUS ='C') END AS KEP_DEPT_CODE , IV.AGENT AS AGENT , IV.DESCRIPTION AS DESCRIPTION , IV.SPECIFICATION AS SPECIFICATION , SUBSTR(IV.DELIVERY_DATE,1,6) , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'VC04' AND CODE = 'KA') AS KEP_COM_CODE , 'KA' AS SITE_GUBUN_CODE , 'Y' AS NTS_SEND_FLAG , CM.CMP_CLOSE_FLAG AS CMP_CLOSE_FLAG , (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) AS TAX_TYPE , USR.USER_NAME_LOC , (SELECT SP_TYPE FROM SUPLINFO2 WHERE SUPPLIER = IV.AGENT) AS SP_TYPE FROM ICOMIVDT IV /* 구매사별 입고정보 */ , ICOMCMPY CM /* 회원사정보 */ , ICOMPOHD POHD /* 발주 마스터정보 */ , ICOMCOD1 COD /* 마스터코드 관리 */ , ICOMPODT PODT /* 발주 제품정보 */ , V_VOC_ICOMCMPY BCM /* (ICOMCMPY - 회원사정보, MIS_BUYER_MNG - 고객사별 담당자 정보) */ , ICOMLUSR USR /* 발주자 정보 */ WHERE 1=1 AND IV.DELIVERY_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND IV.STATUS <> 'D' AND POHD.STATUS <> 'D' AND BCM.SYS_TYPE = 'KA' AND PODT.STATUS <> 'D' AND IV.AGENT = CM.COM_CODE AND IV.BUYER = BCM.COM_CODE AND NVL(IV.AP_BILL_FLAG,'N') = 'N' AND IV.BUYER IN (select text1 from ICOMCOD1 WHERE TYPE = 'HUB') AND IV.BUYER = POHD.BUYER AND IV.PO_NO = POHD.PO_NO AND IV.BUYER = PODT.BUYER AND IV.PO_NO = PODT.PO_NO AND IV.PO_SEQ = PODT.PO_SEQ AND IV.PROCESS_TYPE = '1' AND IV.AGENT NOT IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT4 = 'S' AND FLAG = 'Y') AND POHD.DOC_TYPE <> 'X' AND IV.BUYER = COD.TEXT1(+) AND IV.AGENT = COD.TEXT2(+) AND COD.TYPE(+) = 'TX07' AND IV.AGENT NOT IN (SELECT TEXT3 FROM ICOMCOD1 WHERE TYPE = 'TX08' AND TEXT1 = 'AP' AND TEXT2 = 'KA') AND POHD.ADD_USER_ID = USR.USER_ID(+)
AND IV.BUYER = #{st_buyer_code}
AND IV.AGENT = #{st_agent_code}
AND IV.PO_NO LIKE #{st_po_no}
AND (SELECT TAX_TYPE FROM ICOMBYIT BYIT WHERE BYIT.BUYER = PODT.BYIT_COMORG_CODE AND BYIT.BUYER_ITEM_NO = PODT.BUYER_ITEM_NO) = #{st_tax_type} /* 과세구분 */
AND IV.BUYER IN ( SELECT IV.BUYER FROM ICOMCOD3 COD3 WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= 'ALL' AND COD3.CODE2 = #{st_user_id} UNION ALL SELECT MNG.BUYER FROM ICOMCOD3 COD3, MIS_BUYER_MNG MNG WHERE COD3.BUYER = 'KRKORE0001' AND COD3.TYPE = 'CMPY' AND COD3.CODE1= MNG.KEP_DEPT AND COD3.CODE2 = #{st_user_id} AND MNG.YEAR = TO_CHAR(SYSDATE,'YYYY') AND MNG.STATUS = 'C' UNION ALL SELECT MNG.BUYER FROM MIS_BUYER_MNG MNG WHERE YEAR = TO_CHAR(SYSDATE,'YYYY') AND STATUS = 'C' AND KEP_USER_ID = #{st_user_id} UNION ALL SELECT COD.CODE1 FROM ICOMCOD3 COD , ICOMCMPY CMPY WHERE COD.BUYER = 'KRKORE0001' AND COD.TYPE = 'CMPY' AND COD.CODE1 = CMPY.COM_CODE AND COD.CODE2 = #{st_user_id} AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN TEXT2 AND TEXT3 )
AND USR.USER_NAME_LOC LIKE '%' || #{st_purchaser_name} || '%'
ORDER BY DELIVERY_DATE , PO_NO , INV_NO , INV_SEQ

mapper.update:
/*updateMasterCmClPurchaseTaxsheetIndividualCreation*/

		UPDATE 
		    ICOMGRDT GR
		SET 
		    AP_CLOSE_DEPT = LPAD(#{KEP_DEPT}, 3, 0)
		    ,NTS_SEND_FLAG = #{NTS_SEND_FLAG}
		WHERE 1=1
		AND BUYER = #{BUYER}
		AND GR_NO = #{GR_NO}
		AND GR_SEQ = #{GR_SEQ}

/*updateMasterCmClPurchaseTaxsheetIndividualCreation_v2*/

		UPDATE 
		    ICOMIVDT IV
		SET 
		    AP_CLOSE_DEPT = LPAD(#{KEP_DEPT}, 3, 0)
		WHERE 1=1
		AND BUYER = #{BUYER}
		AND INV_NO = #{INV_NO}
		AND INV_SEQ = #{INV_SEQ}

/*updateMasterCmClPurchaseTaxsheetIndividualCreation_ICOMGRDT*/

		UPDATE 
		    ICOMGRDT /* 구매사별 입고정보 */
		SET
		    AP_TAX_BILL_NO      = #{order_no}
		  , AP_CLOSE_DEPT       = LPAD(#{dept_code},3,0)
		  , AP_CLOSE_MONTH      = #{issue_date}
		  , AP_CLOSE_REVISION   = #{st_close_revision}
		  , AP_BILL_FLAG        = 'Y'
		WHERE 1=1
		AND (BUYER , GR_NO, GR_SEQ) IN ( ( #{key_buyer}, #{key_gr_no}, #{key_gr_seq} ) )

/*updateMasterCmClPurchaseTaxsheetIndividualCreation_ICOMIVDT_v2*/

		UPDATE 
		    ICOMIVDT /* 구매사별 납품정보 */
		SET
		    AP_TAX_BILL_NO      = #{order_no}
		  , AP_CLOSE_DEPT       = LPAD(#{dept_code},3,0)
		  , AP_CLOSE_MONTH      = #{issue_date}
		  , AP_CLOSE_REVISION   = #{st_close_revision}
		  , AP_BILL_FLAG        = 'Y'
		  , AP_CLOSE_USER_ID	= #{st_user_id}
		WHERE 1=1
		AND (BUYER , INV_NO, INV_SEQ) IN ( ( #{key_buyer}, #{key_inv_no}, #{key_inv_seq} ) )
